  OR NEW.prev_hash <> COALESCE((SELECT hash FROM audit_log WHERE seq = (SELECT MAX(seq) FROM audit_log)), zeroblob(32))
BEGIN SELECT RAISE(ABORT, 'audit_log chain link violated'); END;

